function helperPreflight(c){const tmp='/tmp/prhm-v10-dashboard-helper-'+process.pid+'.js';try{fs.writeFileSync(tmp,c.helper,{mode:0o700});const r=exec('/usr/local/bin/prhm-node',[tmp,'--preflight-only'],{timeout:90000});const x=JSON.parse(String(r.stdout||'').trim());if(x.ok!==true||x.preflight_only!==true||x.action!==ACTION||x.auth_mutation!==false||x.old_plaintext_credentials_present!==true||x.database_mutation!==false||x.business_mutation!==false||x.p0_live!==false||x.p0_decision!==false||x.proposal_send!==false||x.bid_send!==false||x.auto_send!==false)fail('reset_helper_preflight_invalid');return x}finally{try{fs.unlinkSync(tmp)}catch{}}}
function restart(){exec('/usr/bin/systemctl',['restart','prhm-company-approval.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-selfmaint.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-selfmaint-exec.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-mcp.service']);return {base:unixHealth('/run/prhm-agent-selfmaint/selfmaint.sock'),self:unixHealth('/run/prhm-agent-selfmaint-exec/exec.sock',VERSION),mcp:loopHealth(8123)}}
function main(){const args=process.argv.slice(2);if(args.length>1||(args.length===1&&args[0]!=='--preflight-only'))fail('unexpected_arguments');if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');baseline();const {o,c,pluginSha}=candidate();validate(c);const hp=helperPreflight(c);const report={ok:true,schema_version:'prhm.host-action-bootstrap-preflight.v1',preflight_only:args[0]==='--preflight-only',action:ACTION,current_hashes:EXPECTED,candidate_hashes:{base:shaBuf(Buffer.from(c.base)),executor:shaBuf(Buffer.from(c.executor)),plugin:pluginSha,policy:shaBuf(Buffer.from(c.policy)),v4helper:shaBuf(Buffer.from(c.v4helper)),helper:HELPER_SHA},target_version:VERSION,helper_preflight:hp,credentials_rotated:false,database_mutation:false,business_mutation:false,p0_live:false,p0_decision:false,proposal_send:false,bid_send:false,production_mutation:false};if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(report)+'\n');return}const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backup='/var/backups/prhm-host-actions-v10-company-os-dashboard-credential-reset-'+stamp;fs.mkdirSync(backup,{recursive:true,mode:0o700});const modes={base:0o755,executor:0o755,plugin:0o644,policy:0o644,v4helper:0o755};for(const k of ['base','executor','plugin','policy','v4helper']){const dst=path.join(backup,k+'-'+path.basename(FILES[k])+'.bak');fs.copyFileSync(FILES[k],dst,fs.constants.COPYFILE_EXCL);fs.chmodSync(dst,0o600)}let ok=false;try{atomic(FILES.helper,c.helper,0o755);for(const k of ['base','executor','plugin','policy','v4helper'])atomic(FILES[k],c[k],modes[k]);for(const k of ['base','executor','plugin','policy','v4helper'])if(sha(FILES[k])!==report.candidate_hashes[k])fail('post_sha_mismatch:'+k);if(sha(FILES.helper)!==HELPER_SHA)fail('helper_post_sha_mismatch');const health=restart();const p=JSON.parse(fs.readFileSync(FILES.policy,'utf8'));const op='host_action.company_os_dashboard_credentials_reset_v1';if(p.operations?.[op]?.level!==4)fail('policy_operation_postverify_failed');if(!p.typed_scopes.some(x=>x&&x.action===ACTION&&x.operation===op&&x.risk==='critical'))fail('policy_scope_postverify_failed');if(!fs.readFileSync(FILES.plugin,'utf8').includes(ACTION))fail('plugin_enum_postverify_failed');if(!fs.readFileSync(FILES.v4helper,'utf8').includes(pluginSha))fail('v4_plugin_sha_postverify_failed');ok=true;process.stdout.write(JSON.stringify({ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,version:VERSION,action:ACTION,helper_sha256:HELPER_SHA,mcp_plugin_sha256:pluginSha,approval_policy_version:p.version,health,credentials_rotated:false,database_mutation:false,business_mutation:false,p0_live:false,p0_decision:false,proposal_send:false,bid_send:false,backup_dir:backup})+'\n')}finally{if(!ok){try{for(const k of ['base','executor','plugin','policy','v4helper']){const src=path.join(backup,k+'-'+path.basename(FILES[k])+'.bak');if(fs.existsSync(src))atomic(FILES[k],fs.readFileSync(src),modes[k])}try{fs.unlinkSync(FILES.helper)}catch(e){if(e.code!=='ENOENT')throw e}restart()}catch(rb){process.stderr.write('rollback_failed:'+String(rb&&rb.stack||rb)+'\n')}}}}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+'\n');process.exit(1)}
